package com.happy.frame.diagnostics;
import android.app.Activity; import android.os.*; import android.content.*; import android.widget.*;
public class MainActivity extends Activity {
 TextView log; Handler h=new Handler(); public void onCreate(Bundle b){super.onCreate(b);startForegroundService(new Intent(this,LanControlService.class));LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,30,24,20);TextView title=new TextView(this);title.setText("프레임 제스처 진단\n센서 입력: PC 감시 연결 중 표시\n매핑 인식: Key Mapper가 동작을 요청했음을 표시\n사진 변경 성공이나 사용자가 의도한 방향까지 판정하지는 않습니다.");title.setTextSize(20);l.addView(title);Button pair=new Button(this);pair.setText("Home Assistant 연결 코드 표시 (8788)");pair.setOnClickListener(v->LanControlService.localPair());l.addView(pair);Button settings=new Button(this);settings.setText("밝기 제어 권한 설정");settings.setOnClickListener(v->startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_WRITE_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))));l.addView(settings);Button accessibility=new Button(this);accessibility.setText("접근성 서비스 설정");accessibility.setOnClickListener(v->startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS)));l.addView(accessibility);Button revoke=new Button(this);revoke.setText("HA 연결 토큰 모두 해제");revoke.setOnClickListener(v->new android.app.AlertDialog.Builder(this).setMessage("모든 HA 연결을 해제할까요?").setPositiveButton("해제",(d,w)->{getSharedPreferences("lan",0).edit().remove("tokens").apply();}).setNegativeButton("취소",null).show());l.addView(revoke);Switch s=new Switch(this);s.setText("동작 확인 토스트: 항상 켜짐");s.setChecked(true);s.setEnabled(false);l.addView(s);Button test=new Button(this);test.setText("토스트 표시 시험");test.setOnClickListener(v->EventReceiver.show(this,"진단 토스트 표시 정상"));l.addView(test);Button check=new Button(this);check.setText("10초 동안 제스처 입력 확인");check.setOnClickListener(v->{long start=System.currentTimeMillis();EventReceiver.show(this,"10초 안에 손짓을 해 주세요");h.postDelayed(()->{long last=getSharedPreferences("diag",0).getLong("last",0);String msg=last>=start?"입력 관찰됨 — 아래 기록 확인":"입력이 관찰되지 않음 — PC 감시 연결과 센서 상태 확인";EventReceiver.show(this,msg);},10000);});l.addView(check);Button back=new Button(this);back.setText("Immich로 복귀");back.setOnClickListener(v->{Intent i=getPackageManager().getLaunchIntentForPackage("de.ozerov.fully");if(i!=null)startActivity(i);});l.addView(back);ScrollView scroll=new ScrollView(this);log=new TextView(this);log.setTextSize(16);scroll.addView(log);l.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(l);h.post(new Runnable(){public void run(){log.setText(getSharedPreferences("diag",0).getString("log","아직 관찰한 입력이 없습니다."));h.postDelayed(this,1000);}});}
 public void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}
}
